/*
 * gql_tz.h
 *    Named time zones from the IANA time zone database: the UTC offset of a
 *    zone at an instant or at a local wall-clock time, with daylight saving
 *    and historical (local mean time) offsets. Data in gql_tzdata.c,
 *    generated by scripts/gen_tzdata.py.
 */

#ifndef GQL_TZ_H
#define GQL_TZ_H

#include <stdbool.h>
#include <stdint.h>

typedef struct {
    int64_t utc;      /* first UTC second with this offset */
    int32_t offset;   /* seconds east of UTC */
} gql_tz_transition;

typedef struct {
    const char *name;
    int32_t initial_offset;              /* before the first transition */
    const gql_tz_transition *transitions;
    int count;
} gql_tz_zone;

extern const gql_tz_zone gql_tz_zones[];
extern const int gql_tz_zone_count;

/* The zone with this IANA name, or NULL. */
const gql_tz_zone *gql_tz_find(const char *name);

/* Offset (seconds east of UTC) of the zone at a UTC instant. */
int32_t gql_tz_offset_at_utc(const gql_tz_zone *zone, int64_t utc);

/* Offset of the zone at a local wall-clock time, given as seconds since
 * 1970-01-01T00:00 local. In an overlap (clocks go back) the earlier
 * offset; in a gap (clocks go forward) the offset before the gap. */
int32_t gql_tz_offset_at_local(const gql_tz_zone *zone, int64_t local);

/* "+HH:MM", or "+HH:MM:SS" when the offset has seconds (local mean time). */
void gql_tz_format_offset(int32_t offset, char *buf, int buflen);

#endif /* GQL_TZ_H */
